// One-off backfill of an Intent table. Body:
//   { client, base, table, datasetIds: [...], roles: [...], passes: [...], email_campaign }
// client = Hub Clients record id (for the log row); base/table = the Intent table;
// datasetIds = Apify datasets still retrievable (jobs pass); roles = the play's roles line (role pass);
// passes = which fills to run, any of: jobs, company, contacts, role, campaigns, liurl, arkurl.
// Default: all except liurl and arkurl.
// liurl (ruling 2026-08-25, first pass): mismatched URLs re-derived from DiscoLike or blanked.
// arkurl (ruling 2026-08-25, second pass): AI-Ark is the LinkedIn identity authority. Looks the
// person up by name + domain and writes their canonical profile URL. arkurl_scope on the body:
// 'blanked' (default) = Supersoniq rows with an empty URL (restores contacts lost to the guard);
// 'all-supersoniq' = every Supersoniq row, verifying and replacing standing URLs too.
// email_campaign = PlusVibe campaign id written as Email Campaign where blank (campaigns pass).
const sd=$getWorkflowStaticData('global');
sd.runStartedAt=$now.toMillis();
const b=($input.first().json||{}).body||{};
const list=(v)=>Array.isArray(v)?v.map(String):String(v||'').split(',').map(s=>s.trim()).filter(Boolean);
const passes=list(b.passes); const all=!passes.length;
const cfg={ client:String(b.client||''), base:String(b.base||''), table:String(b.table||''), datasetIds:list(b.datasetIds), roles:list(b.roles), email_campaign:String(b.email_campaign||''),
  arkurl_scope:String(b.arkurl_scope||'blanked'),
  do:{ jobs: all||passes.includes('jobs'), company: all||passes.includes('company'), contacts: all||passes.includes('contacts'), role: all||passes.includes('role'), campaigns: all||passes.includes('campaigns'), liurl: passes.includes('liurl'), arkurl: passes.includes('arkurl') } };
const missing=[];
if(!cfg.client) missing.push('client'); if(!cfg.base) missing.push('base'); if(!cfg.table) missing.push('table');
if(cfg.do.role&&!cfg.roles.length) missing.push('roles (needed for the role pass)');
if(missing.length) throw new Error('Backfill launch missing: '+missing.join(', '));
return [{ json: cfg }];

// One item per Apify dataset to fetch. Zero datasets still emits a placeholder so the chain
// reaches Build Writes (Signal Detail parsing needs no dataset).
const cfg=$('Parse Launch').first().json;
const ids=cfg.datasetIds||[];
if(!ids.length) return [{ json: { _empty:true } }];
return ids.map(id=>({ json: { datasetId:id } }));

// Domain Calls: one item per distinct domain that still needs company fields or the in-role
// count. Carries the BizData URL, the Supersoniq match body and the DiscoLike count URL.
// The role terms are the play's roles line, passed on the launch body.
const cfg=$('Parse Launch').first().json;
const parse=(b)=>{ if(typeof b!=='string') return b; try{ return JSON.parse(b); }catch(e){ return null; } };
const roles=Array.isArray(cfg.roles)?cfg.roles:[];
const terms=roles;
const rows=$('Fetch Rows').all().map(i=>i.json).filter(r=>r&&r.id);
const has=(f,k)=>{ const v=f[k]; return v!==undefined&&v!==null&&String(v).trim()!==''; };
const need={};
for(const r of rows){
  const f=r.fields||{}; const d=String(f['Domain']||'').toLowerCase().trim(); if(!d) continue;
  const n=need[d]||(need[d]={ company:false, role:false });
  if(cfg.do.company&&!has(f,'Description')&&!has(f,'Industry Groups')) n.company=true;
  if(cfg.do.role&&terms.length&&!has(f,'Existing In Role')) n.role=true;
}
const out=[];
for(const d of Object.keys(need)){
  const n=need[d]; if(!n.company&&!n.role) continue;
  const q=['domain='+encodeURIComponent(d)].concat(terms.map(t=>'title='+encodeURIComponent(t))).join('&');
  out.push({ json: { domain:d, want_company:n.company, want_role:n.role, roles, terms,
    biz_url: 'https://api.discolike.com/v1/bizdata?domain='+encodeURIComponent(d),
    sq: { companies:[{ domain:d }], filters:{ job_titles:terms } },
    cg_url: 'https://api.discolike.com/v1/contacts/count?'+q } });
}
if(!out.length) return [{ json: { _empty:true, domain:'', biz_url:'https://api.discolike.com/v1/bizdata?domain=none.invalid', cg_url:'https://api.discolike.com/v1/contacts/count?domain=none.invalid', sq:{ companies:[{ domain:'none.invalid' }] } } }];
return out;

// Contact Lookups: one item per row that needs a DiscoLike /contacts/discover call, two modes.
//
// mode 'contact' (contacts pass): rows lacking Seniority; DiscoLike in domain mode with the
// name as filter, capped at 2; Build Writes accepts a result only when its LinkedIn URL matches
// the row's, never on name alone.
//
// mode 'liurl' (liurl pass, Operator ruling 2026-08-25): rows whose LinkedIn URL slug carries
// neither first nor last name (URL-decoded, diacritic-stripped compare). Same DiscoLike call;
// Build Writes matches the returned contact by exact normalised full name, keeps its URL only
// when it passes the same name guard, else blanks the row's URL (row becomes email-only).
const cfg=$('Parse Launch').first().json;
const rows=$('Fetch Rows').all().map(i=>i.json).filter(r=>r&&r.id);
const has=(f,k)=>{ const v=f[k]; return v!==undefined&&v!==null&&String(v).trim()!==''; };
const stripName=(s)=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');
const liSlug=(u)=>{ const m=String(u||'').match(/linkedin\.com\/in\/([^/?#]+)/i); if(!m) return null; let s=m[1]; try{ s=decodeURIComponent(s); }catch(e){} return stripName(s); };
const liMatch=(url,first,last)=>{ const slug=liSlug(url); if(slug===null||!slug) return null; const f=stripName(first), l=stripName(last); if(f.length<2&&l.length<2) return null; return (f.length>=2&&slug.includes(f))||(l.length>=2&&slug.includes(l)); };
const firstOf=(n)=>String(n||'').trim().split(/\s+/)[0]||'';
const lastOf=(n)=>{ const p=String(n||'').trim().split(/\s+/); return p.length>1?p.slice(1).join(' '):''; };
const out=[];
if(cfg.do.contacts){
  for(const r of rows){
    const f=r.fields||{};
    if(has(f,'Seniority')) continue;
    const li=String(f['LinkedIn URL']||'').trim(); const d=String(f['Domain']||'').toLowerCase().trim(); const name=String(f['Name']||'').trim();
    if(!li||!d||!name) continue;
    out.push({ json: { mode:'contact', id:r.id, domain:d, linkedin:li, name, cg:{ domain:[d], name, has_linkedin:true, max_companies:1, results_by_company:2 } } });
  }
}
if(cfg.do.liurl){
  for(const r of rows){
    const f=r.fields||{};
    const li=String(f['LinkedIn URL']||'').trim(); const d=String(f['Domain']||'').toLowerCase().trim(); const name=String(f['Name']||'').trim();
    if(!li||!d||!name) continue;
    if(liMatch(li, firstOf(name), lastOf(name))!==false) continue;                       // only mismatched URLs
    out.push({ json: { mode:'liurl', id:r.id, domain:d, linkedin:li, name, cg:{ domain:[d], name, has_linkedin:true, max_companies:1, results_by_company:3 } } });
  }
}
if(!out.length) return [{ json: { _empty:true, id:'', cg:{ domain:['none.invalid'], max_companies:1, results_by_company:1 } } }];
return out;

// Build Writes: for every row of the Intent table, fill what it lacks. Four passes, each only
// writing a field the row does not already carry; rows the live machine produced are left alone.
//
//   jobs      Signal Detail -> Title, Job Title, Job Link, Job Posted, Job ID; Apify datasets
//             (joined on Job ID) -> the full job record
//   company   DiscoLike BizData per domain -> Description, Industry Groups, Employees, Revenue
//             Range, Score, Keywords, Company Status, Start Date, address, Phones, Public
//             Emails, Social URLs, MX Provider, Redirect Domain
//   role      Supersoniq match + DiscoLike count on the scraped roles -> Existing In Role
//             (highest across the sources that know the company; left blank when none does)
//   contacts  DiscoLike contact lookup, accepted only on a LinkedIn URL match -> Seniority,
//             Department, State, Phone; Contact Source = Supersoniq for rows that have none
//             (every row before 2026-08-23 came from Supersoniq)
// Writes go out in PATCH batches of 10.
const cfg=$('Parse Launch').first().json;
const parse=(b)=>{ if(typeof b!=='string') return b; try{ return JSON.parse(b); }catch(e){ return null; } };
const rsp=(it)=>{ const j=(it&&it.json)||{}; return { status:Number(j.statusCode)||0, body:parse(j.body===undefined?null:j.body) }; };
const join=(a)=>Array.isArray(a)?a.filter(Boolean).join(', '):'';
const kv=(o)=>o&&typeof o==='object'?Object.entries(o).map(([k,v])=>k+':'+(typeof v==='number'?v.toFixed(2):v)).join(', '):'';
const firstPhone=(p)=>Array.isArray(p)&&p.length?String((p[0]&&p[0].phone)||p[0]||''):'';
const normLi=(u)=>String(u||'').toLowerCase().replace(/^https?:\/\//,'').replace(/^www\./,'').replace(/\/+$/,'').split('?')[0];
const has=(r,k)=>{ const f=r.fields||{}; const v=f[k]; return v!==undefined&&v!==null&&String(v).trim()!==''; };
const rows=$('Fetch Rows').all().map(i=>i.json).filter(r=>r&&r.id);
const st={ rows:rows.length, parsed:0, unparsed:0, datasets:0, datasetMisses:[], jobsIndexed:0, matched:0, biz_called:0, biz_matched:0, biz_unknown:0, biz_errors:0, role_known:0, role_unknown:0, lookups:0, lookup_matched:0, lookup_nomatch:0, lookup_errors:0, rowsToWrite:0, untouched:0, batches:0, failed:[] };

// jobs pass
const jobs={};
if(cfg.do.jobs){ try{ for(const it of $('Get Dataset').all()){ const r=rsp(it); if(r.status>=200&&r.status<300&&Array.isArray(r.body)){ st.datasets++; for(const job of r.body){ const id=String(job.id||''); if(id&&!jobs[id]){ jobs[id]=job; st.jobsIndexed++; } } } else if(r.status) st.datasetMisses.push('HTTP '+r.status); } }catch(e){} }
const LEGACY=/^Hiring\s+(.+?)\s+\(posted\s+(\d{4}-\d{2}-\d{2})\)\.\s*Decision maker\s+\((.*?)\)\s+via[\s\S]*?Job:\s*(\S+)/;
const LOOSE=/^Hiring\s+(.+?)(?:\s+\(posted\s+(\d{4}-\d{2}-\d{2})\))?[\s\S]*?Job:\s*(\S+)/;
const idFromLink=(link)=>{ const m=String(link||'').match(/-(\d{8,})(?:\?|$)/); return m?m[1]:''; };

// company + role passes, by domain
const biz={}, role={};
try{
  const calls=$('Domain Calls').all().map(i=>i.json).filter(c=>c&&c.domain);
  let bz=[], sq=[], cg=[]; try{ bz=$('BizData').all(); }catch(e){} try{ sq=$('SQ Count').all(); }catch(e){} try{ cg=$('CG Count').all(); }catch(e){}
  calls.forEach((c,i)=>{
    const b=rsp(bz[i]); st.biz_called++;
    if(b.status>=200&&b.status<300&&b.body&&typeof b.body==='object'&&(b.body.domain||b.body.name)){ biz[c.domain]=b.body; st.biz_matched++; }
    else if(b.status===204||b.status===404) st.biz_unknown++;
    else if(b.status){ st.biz_errors++; st.failed.push({ name:'BizData '+c.domain, reason:'HTTP '+b.status }); }
    let known=false, count=0;
    const s=rsp(sq[i]);
    if(s.status>=200&&s.status<300&&s.body&&typeof s.body==='object'){ const m=Array.isArray(s.body.matched)?s.body.matched[0]:(Array.isArray(s.body.results)?s.body.results[0]:null); if(m&&(m.company_id||m.company_name)){ known=true; count=Math.max(count,Number(m.available_contacts)||0); } }
    const g=rsp(cg[i]);
    if(g.status>=200&&g.status<300&&g.body&&typeof g.body==='object'&&g.body.count!==undefined&&biz[c.domain]){ known=true; count=Math.max(count,Number(g.body.count)||0); }
    if(known){ role[c.domain]=count; st.role_known++; } else st.role_unknown++;
  });
}catch(e){}

// contacts + liurl passes, by row id, both fed by the same CG Lookup call aligned by index.
// liurl (Operator ruling 2026-08-25): the row's URL failed the name guard; a replacement is
// accepted only from a DiscoLike contact whose normalised full name equals the row's AND whose
// URL passes the guard itself. No such contact = the URL is blanked, the row stays email-only.
const stripName=(s)=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');
const liSlug=(u)=>{ const m=String(u||'').match(/linkedin\.com\/in\/([^/?#]+)/i); if(!m) return null; let s=m[1]; try{ s=decodeURIComponent(s); }catch(e){} return stripName(s); };
const liMatch=(url,first,last)=>{ const slug=liSlug(url); if(slug===null||!slug) return null; const f=stripName(first), l=stripName(last); if(f.length<2&&l.length<2) return null; return (f.length>=2&&slug.includes(f))||(l.length>=2&&slug.includes(l)); };
const linkedinOf=(urls)=>Array.isArray(urls)?(urls.find(u=>/linkedin\.com\/in\//i.test(u))||''):'';
const firstOf=(n)=>String(n||'').trim().split(/\s+/)[0]||'';
const lastOf=(n)=>{ const p=String(n||'').trim().split(/\s+/); return p.length>1?p.slice(1).join(' '):''; };
st.liurl_checked=0; st.liurl_recovered=0; st.liurl_blanked=0; st.liurl_rows=[];
const contact={}; const liurl={};
try{
  const lk=$('Contact Lookups').all().map(i=>i.json).filter(c=>c&&c.id);
  let res=[]; try{ res=$('CG Lookup').all(); }catch(e){}
  lk.forEach((c,i)=>{
    const r=rsp(res[i]); st.lookups++;
    if(!(r.status>=200&&r.status<300)||!r.body||typeof r.body!=='object'){ st.lookup_errors++; if(r.status) st.failed.push({ name:'Lookup '+c.name, reason:'HTTP '+r.status }); if(c.mode==='liurl'){ st.liurl_checked++; liurl[c.id]=''; st.liurl_blanked++; st.liurl_rows.push(c.name+': blanked (lookup errored)'); } return; }
    const entry=(r.body.results&&(r.body.results[c.domain]||Object.values(r.body.results)[0]))||null;
    const contacts=(entry&&entry.contacts)||[];
    if(c.mode==='liurl'){
      st.liurl_checked++;
      const want=stripName(c.name);
      const hit=contacts.find(p=>stripName(p.name)===want);
      const url=hit?linkedinOf(hit.social_urls):'';
      if(url&&liMatch(url, firstOf(c.name), lastOf(c.name))===true){ liurl[c.id]=url; st.liurl_recovered++; st.liurl_rows.push(c.name+': recovered '+url); }
      else { liurl[c.id]=''; st.liurl_blanked++; st.liurl_rows.push(c.name+': blanked ('+c.linkedin+')'); }
      return;
    }
    const want=normLi(c.linkedin);
    const hit=contacts.find(p=>Array.isArray(p.social_urls)&&p.social_urls.some(u=>normLi(u)===want));
    if(hit){ contact[c.id]=hit; st.lookup_matched++; } else st.lookup_nomatch++;
  });
}catch(e){}

// arkurl pass: AI-Ark identity by row id, aligned by index to Ark Lookups. A hit counts only
// when the returned profile's name matches and its current company domain is the row's domain;
// then its canonical URL is written (overwrite). Left-company or no-match on the 'all' scope
// blanks a standing URL; on the 'blanked' scope there is nothing to blank.
st.ark_checked=0; st.ark_written=0; st.ark_left=0; st.ark_nomatch=0; st.ark_errors=0; st.ark_rows=[];
const arkRes={};
try{
  const lk=$('Ark Lookups').all().map(i=>i.json).filter(c=>c&&c.id);
  let res=[]; try{ res=$('Ark Search').all(); }catch(e){}
  lk.forEach((c,i)=>{
    const r=rsp(res[i]); st.ark_checked++;
    if(!(r.status>=200&&r.status<300)||!r.body||typeof r.body!=='object'){ st.ark_errors++; st.failed.push({ name:'Ark '+c.name, reason:'HTTP '+r.status }); return; }
    const hits=Array.isArray(r.body.content)?r.body.content:[];
    const want=stripName(c.name);
    const named=hits.filter(h=>h&&h.profile&&stripName(h.profile.full_name)===want);
    const pool=named.length?named:hits;
    if(!pool.length){ st.ark_nomatch++; arkRes[c.id]=''; st.ark_rows.push(c.name+': no profile found at '+c.domain); return; }
    const hit=pool.find(h=>c.linkedin&&h.link&&String(h.link.linkedin||'').toLowerCase()===c.linkedin.toLowerCase())||pool[0];
    const curDomain=String(((hit.company||{}).link||{}).domain||'').toLowerCase().trim();
    if(curDomain&&curDomain!==c.domain){ st.ark_left++; arkRes[c.id]=''; st.ark_rows.push(c.name+': now at '+curDomain+', no URL'); return; }
    const url=String((hit.link||{}).linkedin||'').trim();
    if(url){ arkRes[c.id]=url; st.ark_written++; st.ark_rows.push(c.name+': '+url); }
    else { st.ark_nomatch++; arkRes[c.id]=''; st.ark_rows.push(c.name+': profile has no URL'); }
  });
}catch(e){}

const writes=[];
for(const r of rows){
  const f=r.fields||{}; const out={};
  const put=(k,v)=>{ if(v!==undefined&&v!==null&&String(v).trim()!==''&&!has(r,k)) out[k]=v; };
  // jobs
  if(cfg.do.jobs){
    const sd=String(f['Signal Detail']||'');
    let jobTitle='', posted='', contactTitle='', link='';
    let m=sd.match(LEGACY); if(m){ jobTitle=m[1]; posted=m[2]; contactTitle=m[3]; link=m[4]; } else { m=sd.match(LOOSE); if(m){ jobTitle=m[1]; posted=m[2]||''; link=m[3]; } }
    if(m){ st.parsed++;
      const jobId=has(r,'Job ID')?String(f['Job ID']):idFromLink(link);
      put('Title',contactTitle.trim()); put('Job Title',jobTitle.trim()); put('Job Link',link.replace(/[.,;]+$/,'')); put('Job Posted',posted); put('Job ID',jobId);
      const job=jobId?jobs[jobId]:null;
      if(job){ st.matched++; put('Job Description',job.descriptionText); put('Job Seniority',job.seniorityLevel); put('Job Function',job.jobFunction); put('Job Employment Type',job.employmentType); put('Job Industries',job.industries); if(!has(r,'Job Applicants')&&Number(job.applicantsCount)) out['Job Applicants']=Number(job.applicantsCount); put('Job Salary',job.salary); put('Job Poster Name',job.jobPosterName); put('Job Poster Title',job.jobPosterTitle); put('Job Poster LinkedIn',job.jobPosterProfileUrl); }
    } else st.unparsed++;
  }
  const d=String(f['Domain']||'').toLowerCase().trim();
  // company
  const b=d?biz[d]:null;
  if(cfg.do.company&&b){ const addr=b.address||{};
    put('Description',b.description); put('Industry Groups',kv(b.industry_groups)); put('Employees',b.employees); put('Revenue Range',b.revenue_range); put('Score',b.score!=null?String(b.score):''); put('Keywords',b.keywords?Object.keys(b.keywords).join(', '):'');
    put('Company Status',b.status?(b.status.status+(b.status.confidence!=null?' ('+b.status.confidence+')':'')):''); put('Start Date',b.start_date); put('Street',addr.street); put('Company City',addr.city); put('Company State',addr.state); put('Country',addr.country); put('Zip',addr.zip);
    put('Phones',join(b.phones)); put('Public Emails',join(b.public_emails)); put('Social URLs',join(b.social_urls)); put('MX Provider',b.mx_provider); put('Redirect Domain',b.redirect_domain); }
  // role
  if(cfg.do.role&&d&&role[d]!==undefined&&!has(r,'Existing In Role')) out['Existing In Role']=role[d];
  // campaigns: carry the old single Target Campaign into the channel fields; Email Campaign from the launch body
  if(cfg.do.campaigns){
    const tc=String(f['Target Campaign']||'').trim();
    if(tc&&/^https?:\/\//i.test(tc)){ put('LinkedIn Campaign',tc); if(String(f['Intent Status']||'')==='ROUTED'&&f['routed_at']) put('LinkedIn Routed At',f['routed_at']); }
    else if(tc){ put('Email Campaign',tc); if(String(f['Intent Status']||'')==='ROUTED'&&f['routed_at']) put('Email Routed At',f['routed_at']); }
    if(cfg.email_campaign) put('Email Campaign',cfg.email_campaign);
  }
  // contacts
  if(cfg.do.contacts){
    const p=contact[r.id];
    if(p){ put('Seniority',p.seniority); put('Department',p.department); put('State',p.state); put('Phone',firstPhone(p.phone)); }
    if(!has(r,'Contact Source')) out['Contact Source']='Supersoniq';
  }
  // liurl: overwrite deliberately, recovered URL or blank; the only pass allowed to clear a cell.
  if(cfg.do.liurl&&liurl[r.id]!==undefined&&liurl[r.id]!==String(f['LinkedIn URL']||'').trim()) out['LinkedIn URL']=liurl[r.id];
  // arkurl: AI-Ark's canonical URL overwrites; a verified departure or no-match blanks it.
  if(cfg.do.arkurl&&arkRes[r.id]!==undefined&&arkRes[r.id]!==String(f['LinkedIn URL']||'').trim()) out['LinkedIn URL']=arkRes[r.id];
  if(!Object.keys(out).length){ st.untouched++; continue; }
  writes.push({ id:r.id, fields:out });
}
st.rowsToWrite=writes.length;
const batches=[];
for(let i=0;i<writes.length;i+=10) batches.push({ json: { records:writes.slice(i,i+10), typecast:true } });
st.batches=batches.length;
if(!batches.length) return [{ json: { _empty:true, _stats:st } }];
batches[0].json._stats=st;
return batches;

// One row per run, per the logging standard. Status from failed[]; nothing-to-do is a skip.
const sd=$getWorkflowStaticData('global'); const rs=sd.runStartedAt||0;
const cfg=$('Parse Launch').first().json||{};
const nf=(x)=>Number(x||0).toLocaleString('en-US');
let st={};
try{ const s=$('Build Writes').first().json._stats; if(s) st=s; }catch(e){}
const failed=[].concat(st.failed||[]);
let written=0;
try{ for(const it of $('Write Rows').all()){ const j=it.json||{}; const status=Number(j.statusCode)||0; let body=j.body; if(typeof body==='string'){ try{ body=JSON.parse(body); }catch(e){} }
  if(status>=200&&status<300&&body&&Array.isArray(body.records)) written+=body.records.length; else failed.push({ name:'batch', reason:'HTTP '+status+' '+String((body&&body.error&&(body.error.message||body.error.type))||'').slice(0,120) }); } }catch(e){}
for(const m of (st.datasetMisses||[])) failed.push({ name:'Apify dataset', reason:m });
const errs=failed.length;
const passes=Object.entries(cfg.do||{}).filter(([k,v])=>v).map(([k])=>k).join(', ');
const lines=[
  '**'+nf(written)+' rows backfilled of '+nf(st.rows)+', '+errs+' error'+(errs===1?'':'s')+'**',
  '',
  '**Table:** '+(cfg.table||'')+' in '+(cfg.base||'')+' · **Passes:** '+passes,
  '',
  '**Funnel**',
  '- **Rows read:** '+nf(st.rows),
  '- **Jobs:** Signal Detail parsed '+nf(st.parsed)+' · unparsed '+nf(st.unparsed)+' · datasets '+nf(st.datasets)+' of '+nf((cfg.datasetIds||[]).length)+' · jobs indexed '+nf(st.jobsIndexed)+' · rows matched '+nf(st.matched),
  '- **Company:** BizData '+nf(st.biz_called)+' domains · matched '+nf(st.biz_matched)+' · unknown '+nf(st.biz_unknown)+' · errors '+nf(st.biz_errors),
  '- **Role:** Existing In Role known for '+nf(st.role_known)+' domains · unknown '+nf(st.role_unknown),
  '- **Contacts:** '+nf(st.lookups)+' lookups · matched on LinkedIn '+nf(st.lookup_matched)+' · no match '+nf(st.lookup_nomatch)+' · errors '+nf(st.lookup_errors),
  '- **Rows with something to write:** '+nf(st.rowsToWrite)+' · already complete '+nf(st.untouched),
  '- **Written:** '+nf(written)+' in '+nf(st.batches)+' batches'
];
if(st.liurl_checked) lines.splice(lines.length-2, 0, '- **LinkedIn URL guard:** '+nf(st.liurl_checked)+' mismatched · recovered '+nf(st.liurl_recovered)+' · blanked (email-only) '+nf(st.liurl_blanked));
if(st.ark_checked) lines.splice(lines.length-2, 0, '- **AI-Ark identity:** '+nf(st.ark_checked)+' looked up · URL written '+nf(st.ark_written)+' · left company '+nf(st.ark_left)+' · no match '+nf(st.ark_nomatch)+' · errors '+nf(st.ark_errors)+' (~'+(Math.round((st.ark_checked||0)*0.5*10)/10)+' credits)');
const liRows=st.liurl_rows||[];
if(liRows.length) lines.push('','**LinkedIn URL re-derived ('+nf(liRows.length)+')**\n'+liRows.slice(0,40).map(x=>'- '+x).join('\n')+(liRows.length>40?'\n- ...and '+(liRows.length-40)+' more':''));
const arkRows=st.ark_rows||[];
if(arkRows.length) lines.push('','**AI-Ark URL verdicts ('+nf(arkRows.length)+')**\n'+arkRows.slice(0,40).map(x=>'- '+x).join('\n')+(arkRows.length>40?'\n- ...and '+(arkRows.length-40)+' more':''));
if(failed.length) lines.push('','**FAILED ('+failed.length+')**\n'+failed.slice(0,8).map(f=>'- '+f.name+': '+f.reason).join('\n')+(failed.length>8?'\n- ...and '+(failed.length-8)+' more':''));
if(!st.rowsToWrite) lines.push('','Skipped (writes, every row already carries its fields)');
const row={
 'Automation':'Backfill Intent Fields (one-off)',
 'Status': errs?'Succeeded with errors':'Succeeded',
 'Run at': $now.toISO(),
 'Records In': st.rows||0,
 'Records Out': written,
 'Errors': errs,
 'Target': cfg.table||'',
 'Trigger':'webhook',
 'Execution ID': String($execution.id),
 'Execution Link': 'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id,
 'Duration s': Math.round(($now.toMillis()-(rs||$now.toMillis()))/1000),
 'Description': lines.join('\n')
};
if(cfg.client) row['Client']=[cfg.client];
return [{ json: row }];

// Ark Lookups (arkurl pass): one AI-Ark people-search body per target row.
// Scope 'blanked' = Supersoniq rows with no LinkedIn URL (restore the contacts the guard
// blanked, ruling 2026-08-25: LinkedIn matters more than email, nothing is given up).
// Scope 'all-supersoniq' = every Supersoniq row, standing URLs verified and replaced too.
// 0.5 credits per returned result, size 2 so ambiguity is visible.
const cfg=$('Parse Launch').first().json;
const rows=$('Fetch Rows').all().map(i=>i.json).filter(r=>r&&r.id);
const out=[];
if(cfg.do.arkurl){
  for(const r of rows){
    const f=r.fields||{};
    if(String(f['Contact Source']||'')!=='Supersoniq') continue;
    const li=String(f['LinkedIn URL']||'').trim();
    if(cfg.arkurl_scope==='blanked'&&li) continue;
    const name=String(f['Name']||'').trim(); const d=String(f['Domain']||'').toLowerCase().trim();
    if(!name||!d) continue;
    out.push({ json: { id:r.id, name, domain:d, linkedin:li, arkBody:{
      contact:{ fullName:{ any:{ include:{ mode:'SMART', content:[name] } } } },
      account:{ domain:{ any:{ include:[d] } } },
      page:0, size:2 } } });
  }
}
if(!out.length) return [{ json: { _empty:true, id:'', arkBody:{ contact:{ fullName:{ any:{ include:{ mode:'STRICT', content:['zzz-nobody-zzz'] } } } }, account:{ domain:{ any:{ include:['none.invalid'] } } }, page:0, size:1 } } }];
return out;
